sys_script_client.script:
function onLoad() {
  // Proteção caso g_form não esteja disponível
  if (typeof g_form === 'undefined') return;

  // Mensagem traduzível
  var msg = getMessage(
    'Lembrete: informe a data de publicação somente no dia da publicação. ' +
    'Quando o acompanhamento terminar, marque End follow-up para atualizar o Status para Closed.'
  );

  // Exibe mensagem no topo do formulário (Classic UI)
  g_form.addInfoMessage(msg);

  // Opcional: mensagem ao lado do campo publication_date
  // g_form.showFieldMsg('publication_date', 'Informe a data apenas no dia da publicação.', 'info', false);

  // Garante que o campo indicador (se existir) esteja somente leitura e visível
  if (g_form.isNewRecord || g_form.getValue('status_indicator') !== undefined) {
    g_form.setReadOnly('status_indicator', true);
    g_form.setDisplay('status_indicator', true);
  }
}
